pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: deploy, set log to zero address to avoid revert, initialize
        c.SetLogFile(address(0));
        c.Initialized();
        // First SetMinSum succeeds in both
        c.SetMinSum(100);
        // Second SetMinSum: reference succeeds (no effect), bug reverts
        // We catch the revert
        bool secondOk;
        try c.SetMinSum(200) {
            secondOk = true;
        } catch {
            secondOk = false;
        }
        // The reference allows second call, bug reverts; we assert it succeeded
        assertTrue(secondOk);
        // Now call Collect with enough balance. In reference, MinSum=200 (last set) so collect not allowed;
        // but actually we need a concrete divergence: after second call, in reference MinSum=200, in bug MinSum=100 (unchanged).
        // To observe divergence: put 150 wei, then try collect 150 before unlock. Reference: MinSum=200, balance=150 < MinSum => Collect does nothing (no revert). Bug: MinSum=100, balance=150 >= MinSum, and unlockTime=0, but we need timestamp>unlock. Use warp.
        vm.deal(address(this), 1 ether);
        vm.warp(1000);
        // put with lockTime 0, so unlockTime = 1000, not > timestamp. Collect requires block.timestamp > unlockTime, so fails.
        // Let's use Put first with lockTime 0 to set unlockTime=1000.
        c.Put{value: 150}(0);
        // Now timestamp = 1000, unlockTime = 1000, condition block.timestamp > unlockTime fails.
        // To make Collect succeed, we need timestamp > unlockTime. Let's set another lock with longer time? Simpler: use lockTime 100, so unlockTime = 1100, warp to 1101.
        // Reset: new contract
        // Actually we can just use fresh setup. Let me redo.
        c = new C();
        c.SetLogFile(address(0));
        c.Initialized();
        // Set MinSum in bug to 100 (by first call), second call reverts, so MinSum stays 100.
        // In reference, first call sets to 100? Actually first call sets MinSum=100. Second call (allowed) sets MinSum=200.
        // So reference MinSum=200, bug MinSum=100.
        bool secondOk2;
        try c.SetMinSum(100) {
            // first call always succeeds
        } catch {}
        try c.SetMinSum(200) {
            secondOk2 = true;
        } catch {
            secondOk2 = false;
        }
        assertTrue(secondOk2);
        // Now put 150 with lockTime 100, warp to 1101 so unlockTime=100+block.timestamp? But block.timestamp is 0 now, warp to 1101.
        vm.deal(address(this), 1 ether);
        vm.warp(1101);
        // Put with lockTime 0? Actually need unlockTime < block.timestamp. Put with lockTime 0 sets unlockTime = current timestamp (1101). Then Collect requires > unlockTime, so need >1101. Simpler: don't put, just observe MinSum.
        // Just assert MinSum values:
        assertEq(c.MinSum(), 200); // In reference: 200, in bug: 100 -> assertion fails on bug
    }
}

