import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Scenario: call SetMinSum(1), then Initialized, then SetLogFile(address(this))
        c.SetMinSum(1);
        c.Initialized();
        // SetLogFile should revert in reference (because intitalized is true) but succeed in buggy version
        bool ok;
        try c.SetLogFile(address(this)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok); // Reference: revert -> ok false, Modified: no revert -> ok true
    }
}

