pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // scenario: user deposits 2 ether, lockTime 0, then tries to collect 1 ether
        address user = address(0x123);
        vm.deal(user, 10 ether);

        // Set minimum sum to 0.5 ether via SetMinSum (buggy version also sets initialized here)
        vm.prank(user);
        c.SetMinSum(0.5 ether);

        // In reference: Initialized is still needed; buggy: SetMinSum already set initialized, so next call will revert
        // We'll call Initialized anyway — in reference it succeeds, in buggy it reverts, but we don't care about revert
        vm.prank(user);
        (bool okInit, ) = address(c).call(abi.encodeWithSignature("Initialized()"));
        // ignore result, state is now: reference: initialized=true; buggy: already true (set in SetMinSum)

        // User puts 2 ether with lockTime=0
        vm.prank(user);
        c.Put{value: 2 ether}(0);

        // Warp past unlockTime (which is 0 + block.timestamp, so already past)
        vm.warp(block.timestamp + 1);

        // Try to collect 1 ether
        vm.prank(user);
        (bool okCollect, ) = address(c).call{value: 0 ether}(abi.encodeWithSignature("Collect(uint256)", 1 ether));

        // Assert that collect succeeded (reference: okCollect true; buggy: false because MinSum was set to 0? Actually buggy: SetMinSum sets MinSum=0.5 ether but also locks initialization; then Initialized() reverts? Let's trace: In buggy, SetMinSum sets MinSum=0.5 ether AND intitalized=true. Then Initialized() call reverts (because if(intitalized)revert();) — but the revert is caught by our call, state unchanged. Then Put succeeds. Then Collect checks: acc.balance (2 ether) >= MinSum (0.5 ether) true, acc.balance >= _am (1 ether) true, block.timestamp > acc.unlockTime true (since lockTime=0). So buggy should also succeed. Hmm, need different scenario.
        // Actually the difference: In the buggy version, SetMinSum sets initialized, so the subsequent Initialized() call reverts (which is fine). But note: the reference version requires that after SetMinSum, Initialized() must be called separately. In buggy, SetMinSum already does both. So both versions end with same state? Wait, the buggy version changes only one line: adds 'intitalized = true;' inside SetMinSum. That means after SetMinSum, the contract is considered initialized. In reference, you still need to call Initialized() separately. But if you call Initialized() after SetMinSum in both, reference succeeds, buggy reverts. However, that revert doesn't break functionality — just the call fails. The key is: in reference, after SetMinSum and then Initialized, the contract is initialized. In buggy, after SetMinSum, it's already initialized, and Initialized() reverts but contract still initialized. Both end with intitalized=true. So where's the observable divergence?
        // The divergence is: if someone tries to call SetMinSum again after initialization, reference reverts, buggy also reverts because intitalized is true. No difference there.
        // Actually look: The buggy version sets intitalized=true inside SetMinSum, but ALSO leaves the SetLogFile and Initialized functions unchanged. So SetLogFile can still be called after SetMinSum (because it checks intitalized). In reference, after SetMinSum, intitalized is still false, so SetLogFile can be called. In buggy, after SetMinSum, intitalized is true, so SetLogFile reverts. That's the divergence!
        // So scenario: call SetMinSum, then call SetLogFile with some address. Reference succeeds, buggy reverts.
        // Let's change to that.
        // But then assertion? We need an assertion that holds for reference and fails for buggy.
        // Use try/catch on SetLogFile.

        address logAddr = address(0x456);
        vm.prank(user);
        bool okSetLog;
        try c.SetLogFile(logAddr) {
            okSetLog = true;
        } catch {
            okSetLog = false;
        }

        assertTrue(okSetLog);  // reference: succeeds (true), buggy: fails (false)
    }
}

